[{"order":1,"type":"heading","text":"Navigation and Page Transitions in NativeScript"},{"order":2,"type":"paragraph","text":"Building fluid multi-page mobile applications requires a solid understanding of routing, frame management, and custom page transitions. In NativeScript, navigation is handled through the Frame module and the Core Router, allowing developers to transition smoothly between different views while maintaining native performance."},{"order":3,"type":"subheading","text":"Basic Navigation Setup"},{"order":4,"type":"paragraph","text":"To navigate between pages in a NativeScript Core or Angular application, you typically use the Frame module or Angular's Router service. Below is an example of how to programmatically navigate to a detail page using the Frame module."},{"order":5,"type":"code","text":"import { Frame } from '@nativescript/core';

function onNavigateTap() {
    Frame.topmost().navigate({
        moduleName: 'details-page',
        context: { itemId: 42 },
        clearHistory: false
    });
}"},{"order":6,"type":"subheading","text":"Customizing Page Transitions"},{"order":7,"type":"paragraph","text":"NativeScript provides native-feeling page transitions out of the box, such as slide, fade, and flip. You can specify these transitions directly inside the navigation options object to override the default platform behavior."},{"order":8,"type":"code","text":"import { Frame, NavigationTransition } from '@nativescript/core';

const transition: NavigationTransition = {
    name: 'slideLeft',
    duration: 300,
    curve: 'easeInOut'
};

Frame.topmost().navigate({
    moduleName: 'profile-page',
    transition: transition
});"},{"order":9,"type":"subheading","text":"Supported Transition Types"},{"order":10,"type":"bullet_point","text":"slide: Slides the new page over the old one horizontally."},{"order":11,"type":"bullet_point","text":"slideTop / slideBottom: Vertical sliding animations."},{"order":12,"type":"bullet_point","text":"fade: Fades the opacity of the incoming view."},{"order":13,"type":"bullet_point","text":"flip: 3D card flip transition effect."},{"order":14,"type":"subheading","text":"Handling Navigation Context"},{"order":15,"type":"paragraph","text":"Passing data during navigation is essential. You can pass objects via the context property and retrieve them on the destination page through the NavigatedData event args."},{"order":16,"type":"code","text":"import { NavigatedData, Page } from '@nativescript/core';

export function onNavigatedTo(args: NavigatedData) {
    const page = <Page>args.object;
    const context = page.navigationContext;
    console.log("Received Item ID: " + context.itemId);
}"},{"order":17,"type":"subheading","text":"Best Practices"},{"order":18,"type":"bullet_point","text":"Always clear history using 'clearHistory: true' when navigating away from authentication or onboarding screens."},{"order":19,"type":"bullet_point","text":"Keep transition durations between 200ms and 400ms to ensure the UI feels responsive and snappy."},{"order":20,"type":"bullet_point","text":"Leverage Angular or Vue routing wrappers if you are using a modern frontend framework with NativeScript."}]
